#include <map>
using namespace std;
class stringx { public: stringx(const char *); stringx(const stringx &); const char *c_str() const; };
stringx operator+(const stringx &, const stringx &);
class entity_id { unsigned int val; public: bool operator==(const entity_id& e) const { return val == e.val; } bool operator<(const entity_id& e) const { return val < e.val; } stringx get_val() const; };
extern const entity_id ANONYMOUS;
class entity { public: entity_id get_id() const; };
class singleton {};
typedef map<entity_id, entity*> entity_map;
class entity_manager : entity_map, public singleton { public: void register_entity(entity*); };
extern void error(const char *);

void entity_manager::register_entity(entity* e)
{
  if( !(e->get_id() == ANONYMOUS) )
  {
    pair<iterator,bool> retval = insert( value_type(e->get_id(), e) );
    if(!retval.second)
    {
      stringx composite = stringx("Same entity name appears twice:")+ e->get_id().get_val();
      error( composite.c_str() );
    }
  }
}
